function trimAsciiWhitespace(bytes: Buffer, start: number, end: number): { start: number; end: number } {
  while (start < end && [9, 10, 13, 32].includes(bytes[start]!)) start += 1;
  while (end > start && [9, 10, 13, 32].includes(bytes[end - 1]!)) end -= 1;
  return { start, end };
}

function safeUtf8End(bytes: Buffer, start: number, desiredEnd: number): number {
  let end = Math.min(bytes.length, desiredEnd);
  while (end > start && end < bytes.length && (bytes[end]! & 0xc0) === 0x80) end -= 1;
  return end > start ? end : Math.min(bytes.length, desiredEnd);
}

function sourceTextParagraphRanges(bytes: Buffer): Array<{ start: number; end: number; text: string }> {
  try { new TextDecoder("utf-8", { fatal: true }).decode(bytes); } catch { throw new Error("science-source-text-utf8-invalid"); }
  const output: Array<{ start: number; end: number; text: string }> = [];
  let start = 0;
  for (let cursor = 0; cursor <= bytes.length; cursor += 1) {
    const atEnd = cursor === bytes.length;
    const separator = !atEnd && bytes[cursor] === 10 && bytes[cursor + 1] === 10;
    if (!atEnd && !separator) continue;
    const trimmed = trimAsciiWhitespace(bytes, start, cursor);
    if (trimmed.end > trimmed.start) output.push({ ...trimmed, text: bytes.subarray(trimmed.start, trimmed.end).toString("utf8") });
    if (separator) {
      while (cursor + 1 < bytes.length && bytes[cursor + 1] === 10) cursor += 1;
      start = cursor + 1;
    }
  }
  return output;
}

function looksLikeSourceSectionHeading(text: string): boolean {
  const normalized = text.replace(/\s+/gu, " ").trim();
  return normalized.length >= 2 && normalized.length <= 160 && !/[.!?。！？:]$/u.test(normalized)
    && normalized.split(" ").length <= 20 && !normalized.includes("\n");
}

