function normalizeResearchEpisodeToolIntents(value: unknown): ScienceResearchEpisodeToolIntent[] {
  if (!Array.isArray(value) || value.length < 1 || value.length > 50) throw new Error("science-research-episode-tool-intents-invalid");
  const intents = value.map((item) => {
    if (!item || typeof item !== "object" || Array.isArray(item)) throw new Error("science-research-episode-tool-intent-invalid");
    const record = item as Record<string, unknown>;
    const toolName = safeText(record.toolName, 160, "research-episode-tool-name");
    const labId = String(record.labId ?? "").toLowerCase();
    if (!LAB_ID_RE.test(labId)) throw new Error("science-research-episode-lab-id-invalid");
    return { toolName, labId, purpose: safeText(record.purpose, 4_000, "research-episode-tool-purpose") };
  });
  if (new Set(intents.map((item) => `${item.toolName}\0${item.labId}\0${item.purpose}`)).size !== intents.length) {
    throw new Error("science-research-episode-tool-intents-duplicate");
  }
  return intents;
}

